import {loadModel,diagnose,labels} from './inference.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let manifest,cases,evidence,current,result,raw,time,setting,uploaded=false,models=new Map(),records=[],analysisGeneration=0;try{records=JSON.parse(localStorage.getItem('aeris_reviews')||'[]')}catch{}
const stages={'':'Initial source training','_cross_adapted':'Cross-setting adaptation','_feedback':'Verified-feedback experiment'};
const architecture={m4_v0:'V0 · Final-step TCN',m4_v1:'V1 · Attention TCN',m4_v2:'V2 · Combined TCN'};
const download=(name,content,type='application/json')=>{let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
const table=(rows,cols,selected=null)=>`<table><thead><tr>${cols.map(([k,t])=>`<th>${esc(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${selected&&r.model===selected?'selected-row':''}">${cols.map(([k,t,format])=>`<td>${esc(format?format(r[k],r):r[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const pct=x=>Number.isFinite(x)?(x*100).toFixed(1)+'%':'—',f1=x=>Number.isFinite(x)?x.toFixed(4):'—',pretty=n=>n.replace('m4_','').replace('_cross_adapted',evidence?.learning?.[n.replace('_cross_adapted','')]?.adaptation_status==='adapted'?' · target update':' · target gate (retained)').replace('_feedback',' · reference feedback').toUpperCase();
const message=(s,error=false)=>{$('#message').innerHTML=s?`<div class="alert ${error?'error':''}">${esc(s)}</div>`:''};
const frame=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
async function getModel(){let key=$('#version').value+$('#stage').value;if(!manifest.models[key])throw Error('This trained bundle is not available.');if(!models.has(key)){message('Loading checksum-verified trained model parameters…');models.set(key,loadModel(manifest.models[key]))}return await models.get(key)}
function selectCase(){if(uploaded)return;current=cases[+$('#case').value];raw=current.raw;time=current.time_s;setting=current.setting;$('#reference').textContent='';$('#reference-toggle').textContent='Show published reference';$('#input-description').textContent='15 one-minute samples · 10 channels · Canonical units'}
function chart(){let colors=['#1a6e60','#8ba743','#d2934f','#7e85ba'],W=620,H=214,pad={l:35,r:14,t:20,b:28};let vals=raw.flatMap(r=>r.slice(0,4)),lo=Math.floor((Math.min(...vals)-2)/5)*5,hi=Math.ceil((Math.max(...vals)+2)/5)*5;if(hi===lo)hi=lo+5;let x=i=>pad.l+i*(W-pad.l-pad.r)/14,y=v=>H-pad.b-(v-lo)/(hi-lo)*(H-pad.t-pad.b);let grid='';for(let j=0;j<5;j++){let v=lo+(hi-lo)*j/4;grid+=`<line x1="${pad.l}" x2="${W-pad.r}" y1="${y(v)}" y2="${y(v)}" stroke="#e9eee5" stroke-dasharray="3 4"/><text x="${pad.l-10}" y="${y(v)+3}" font-size="9" fill="#94a28e" text-anchor="end">${v.toFixed(0)}°</text>`}let paths=colors.map((c,j)=>`<path d="${raw.map((r,i)=>(i?'L':'M')+x(i).toFixed(1)+','+y(r[j]).toFixed(1)).join(' ')}" fill="none" stroke="${c}" stroke-width="2.3" stroke-linecap="round"/>`).join('');$('#sensor-chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Fifteen consecutive minutes of supply, outdoor, mixed and return air temperatures in Celsius">${grid}${paths}${[0,3,7,10,14].map(i=>`<text x="${x(i)}" y="${H-6}" fill="#95a18f" text-anchor="middle" font-size="9">${i===14?'Now':(14-i)+' min ago'}</text>`).join('')}</svg>`;$('#window-caption').textContent=uploaded?'Uploaded CSV · Celsius / fractions · '+setting:current.id+' · '+current.group;}
function render(r){result=r;if(r.status==='blocked'){message('Input blocked: '+r.reasons.join(' '),true);$('#diagnostic-results').hidden=true;return}$('#diagnostic-results').hidden=false;message('');$('#condition').textContent=labels[r.class_id];$('#condition-detail').textContent=setting+' · '+stages[$('#stage').value];$('#confidence').textContent=pct(r.confidence);$('#review').textContent=r.status==='review_required'?'Review required':'Research prediction';$('#review').style.color=r.status==='review_required'?'#a96626':'#256f5e';$('#review-detail').textContent=r.reasons.length?r.reasons.length+' review reason'+(r.reasons.length===1?'':'s'):'Technician confirmation before action';$('#probabilities').innerHTML=r.probabilities.map((p,i)=>`<div class="prob-row"><div class="prob-label"><span>${labels[i]}</span><b>${pct(p)}</b></div><div class="bar-bg"><div class="bar-fill ${i===r.class_id?'selected':''}" style="width:${p*100}%"></div></div></div>`).join('');$('#reasons').innerHTML=r.reasons.length?r.reasons.map(s=>`<li>${esc(s)}</li>`).join(''):'<li class="good">Input and scope checks passed for this recorded setting. Human confirmation is still required.</li>';$('#branch-detail').innerHTML=labels.map((s,i)=>`${esc(s)}: RF ${pct(r.forest_probabilities[i])} · temporal ${pct(r.temporal_probabilities[i])}`).join('<br>')+(r.attention?'<br><br>Attention weights (oldest → newest): '+r.attention.map(x=>x.toFixed(3)).join(', '):'<br><br>V0 summarizes the final encoded step.');chart();}
async function analyze(){let ticket=++analysisGeneration,button=$('#analyze');button.disabled=true;try{let m=await getModel();if(ticket!==analysisGeneration)return;selectCase();let start=performance.now();let r=diagnose(m,raw,setting,time,!uploaded&&current.pool==='Source');render(r);await frame();$('#latency').textContent=(performance.now()-start).toFixed(0)+' ms';$('#architecture-label').textContent=architecture[$('#version').value];$('#model-stage').textContent=stages[$('#stage').value];}catch(e){if(ticket===analysisGeneration)message(e.message,true)}finally{if(ticket===analysisGeneration)button.disabled=false}}
function results(){let rows=evidence.results.filter(r=>r.partition===$('#result-pool').value);$('#results-table').innerHTML=table(rows,[['model','Model',pretty],['macro_f1','Macro F1',f1],['normal_recall','Normal recall',pct],['fault_to_normal','Fault → normal'],['model_review_fraction','Model review',pct],['confident_wrong_090','Wrong ≥ .90']],evidence.selection.selected_initial_bundle);$('#threshold-table').innerHTML=table(evidence.thresholds,[['model','Model',pretty],['threshold','Threshold'],['review_fraction','Review',pct],['wrong_not_reviewed','Wrong unreviewed']]);$('#errors-table').innerHTML=table(evidence.errors.filter(r=>r.role===$('#result-pool').value).slice(0,20),[['model','Model',pretty],['true_class','Reference'],['predicted_class','Prediction'],['confidence','Confidence',pct],['category','Pattern']]);}
function queue(){$('#queue-table').innerHTML=records.length?table(records,[['id','Window'],['label','Inspection label'],['verified','Verified',v=>v?'Yes':'No'],['note','Observation']]):'<p class="caption">No operator reviews saved in this browser.</p>'}
function renderEvidence(){results();let s=evidence.selection;$('#selected-heading').textContent=pretty(s.selected_initial_bundle)+' · provisional research component';$('#selected-reason').textContent=s.decision+' Selection uses source validation; target scores do not determine it. RF-only is a competitive reference; the retained hybrid research design does not establish that temporal modeling improves performance. False-normal errors, latency, complexity and transfer remain part of the decision.';$('#learning-reports').innerHTML=['m4_v0','m4_v1','m4_v2'].map(n=>{let r=evidence.learning[n];return `<h2>${architecture[n]}</h2><div class="learning-item"><article class="card"><p class="eyebrow">INITIAL TRAINING</p><div class="report-num">${r.initial.completed_temporal_epochs} / 50 epochs</div><p class="caption">Fresh RF + NN · best checkpoint ${r.initial.best_temporal_epoch}<br>${r.initial.temporal_parameter_count.toLocaleString()} temporal parameters</p></article><article class="card"><p class="eyebrow">UNLABELED TARGET ADAPTATION</p><div class="report-num">${r.adaptation.selected_windows} selected</div><p>${esc(r.adaptation_status.replaceAll('_',' '))}</p><p class="caption">${r.adaptation.selected_days} days · ${r.adaptation.selected_predicted_classes} predicted classes<br>Fixed gates preserved; no reference labels used.</p></article><article class="card"><p class="eyebrow">VERIFIED REFERENCE FEEDBACK</p><div class="report-num">${r.feedback.selected_windows} labels</div><p>${esc(r.feedback.status.replaceAll('_',' '))}</p><p class="caption">${r.feedback.completed_epochs} candidate epochs · source replay<br>Simulated technician from published references; not a real inspection.</p></article></div>`}).join('');let v=evidence.validation;$('#evidence-cards').innerHTML=[['47 raw files','Pinned source files and split records checked. Ten-channel conversions checked across source and target.'],['150 initial epochs','50 complete epochs for each of three fresh architecture hybrids. Earlier experiments remain separate.'],[v.passed_checks+' checks passed','Model reload, causality, scope controls, version identity and actual Streamlit UI tests.']].map(([h,p])=>`<article class="card"><h2>${esc(h)}</h2><p>${esc(p)}</p></article>`).join('');$('#artifact-links').innerHTML=manifest.artifacts.map(a=>`<a href="${esc(a.url)}" download>${esc(a.label)} ↓</a>`).join('');$('#commit-info').textContent='Implementation commit: '+manifest.code_commit+' · model checksums included in each bundle.';queue();}
function parseCSV(text){let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(quote)throw Error('Malformed quoted CSV.');let header=rows.shift().map(x=>x.trim().replace(/^\uFEFF/,''));if(new Set(header).size!==header.length)throw Error('Duplicate CSV columns.');let keys=['time_s',...manifest.features],indices=keys.map(k=>header.indexOf(k));if(indices.some(i=>i<0)||rows.length!==15)throw Error('CSV needs exactly 15 rows and time_s plus the 10 canonical sensor columns.');let data=rows.map(r=>indices.map(i=>r[i]?.trim()===''?NaN:Number(r[i])));return {time:data.map(r=>r[0]),raw:data.map(r=>r.slice(1))}}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.tab).classList.add('active');window.scrollTo({top:0,behavior:'smooth'})});
$('#analyze').onclick=analyze;$('#version').onchange=analyze;$('#stage').onchange=analyze;$('#case').onchange=()=>{uploaded=false;$('#upload-setting').hidden=true;analyze()};$('#result-pool').onchange=results;$('#upload-trigger').onclick=()=>$('#upload').click();$('#upload-setting').onchange=()=>{setting=$('#upload-setting').value;analyze()};
function applyCSV(text,description){let parsed=parseCSV(text);raw=parsed.raw;time=parsed.time;setting=$('#upload-setting').value;uploaded=true;$('#upload-setting').hidden=false;$('#input-description').textContent=description;$('#reference').textContent='';return analyze()}
$('#paste-trigger').onclick=()=>{$('#paste-panel').hidden=!$('#paste-panel').hidden;$('#upload-setting').hidden=false};
$('#paste-analyze').onclick=async()=>{try{await applyCSV($('#paste-csv').value,'Pasted canonical sensor window')}catch(e){message(e.message,true)}};
$('#upload').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('Upload exceeds the 1 MB window limit.');await applyCSV(await file.text(),'Uploaded: '+file.name)}catch(e){message(e.message,true)}};
$('#sample-download').onclick=()=>{if(!raw)return;download('aeris_sensor_window.csv',['time_s,'+manifest.features.join(','),...raw.map((r,i)=>[time[i],...r].join(','))].join('\n'),'text/csv')};
$('#audit-download').onclick=()=>{if(!result)return;download('aeris_diagnosis_audit.json',JSON.stringify({window_id:uploaded?'uploaded':current.id,setting,model:$('#version').value+$('#stage').value,model_sha256:manifest.models[$('#version').value+$('#stage').value].hybrid_sha256,time_s:time,raw,result:{...result,seq:undefined}},null,2))};
$('#reference-toggle').onclick=()=>{if(uploaded){$('#reference').textContent='No published reference for an uploaded window.';return}$('#reference').textContent=$('#reference').textContent?'':'Published reference: '+labels[current.truth]+' · previously exposed labels; exploratory only.'};
$('#save-note').onclick=()=>{if(!result||result.status==='blocked'){message('Analyze a valid window before saving a review.',true);return}let label=$('#review-label').value,verified=$('#verified').checked,note=$('#review-note').value.trim();if(verified&&label===''){message('Choose an inspection label before marking it verified.',true);return}if(!note){message('Enter an inspection note.',true);return}records.push({id:uploaded?'uploaded-'+crypto.randomUUID():current.id,model:$('#version').value+$('#stage').value,label:label===''?'Unverified':labels[+label],verified,note,time_s:time,raw,created_at:new Date().toISOString(),training_eligible:false,reason:'Operator note; requires reviewed dataset alignment. Saving never changes model weights.'});try{localStorage.setItem('aeris_reviews',JSON.stringify(records));$('#feedback-status').textContent='Saved locally. Weights unchanged; export for controlled review.';message('Review saved. Model weights are unchanged.');queue()}catch{message('Browser storage is full. Export the review queue.',true)}};
$('#queue-download').onclick=()=>download('aeris_operator_review_queue.json',JSON.stringify(records,null,2));
$('#benchmark').onclick=async()=>{let b=$('#benchmark');b.disabled=true;try{let m=await getModel(),samples=cases.slice(0,100),times=[];document.querySelectorAll('.nav,.page').forEach(x=>x.classList.remove('active'));document.querySelector('.nav[data-tab=diagnosis]').classList.add('active');$('#diagnosis').classList.add('active');window.scrollTo(0,0);for(let i=0;i<100;i++){let c=samples[i%samples.length],start=performance.now();raw=c.raw;time=c.time_s;setting=c.setting;current=c;uploaded=false;$('#case').value=String(cases.indexOf(c));$('#upload-setting').hidden=true;render(diagnose(m,raw,setting,time,!uploaded&&current.pool==='Source'));await frame();times.push(performance.now()-start);$('#benchmark-result').textContent=`Rendered ${i+1}/100 warm requests…`}times.sort((a,b)=>a-b);let report={requests:100,p50_ms:times[49],p95_ms:times[94],under_5s:times.filter(x=>x<5000).length,model:$('#version').value+$('#stage').value,included:'Canonical inputs, feature extraction, real RF/TCN inference, policy, DOM update and two animation frames',excluded:'Cold model download and initial page startup',user_agent:navigator.userAgent};window.aerisBenchmark=report;$('#benchmark-result').textContent=`${report.under_5s}/100 under 5s · p50 ${report.p50_ms.toFixed(0)} ms · p95 ${report.p95_ms.toFixed(0)} ms. Cold startup excluded.`;$('#latency').textContent=report.p95_ms.toFixed(0)+' ms';document.querySelectorAll('.nav,.page').forEach(x=>x.classList.remove('active'));document.querySelector('.nav[data-tab=evidence]').classList.add('active');$('#evidence').classList.add('active');$('#benchmark-result').dataset.report=JSON.stringify(report)}catch(e){message(e.message,true)}finally{b.disabled=false}};
async function init(){try{let response=await fetch('manifest.json');if(!response.ok)throw Error('Verified model artifacts are being finalized. Reload after training completes.');manifest=await response.json();[cases,evidence]=await Promise.all([fetch(manifest.cases_url).then(r=>r.json()),fetch(manifest.evidence_url).then(r=>r.json())]);$('#case').innerHTML=cases.map((c,i)=>`<option value="${i}">${esc(c.pool+' · '+c.setting+' · '+String(i+1).padStart(3,'0'))}</option>`).join('');$('#version').value=evidence.selection.selected_initial_bundle;renderEvidence();await analyze();window.aerisReady=true}catch(e){message(e.message,true)}}
init();
